static int pdl_keywords_or_extraction(const ipacket_t *packet, mmt_proto_index_t proto_index, attribute_t *extracted_data)
{
    uint64_t value;

    if (!pdl_keywords_get_or(packet, proto_index, &value)) {
        return 0;
    }
    *(uint8_t *) extracted_data->data = (uint8_t) value;
    return 1;
}

